<?php
require 'config.php'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$items=json_decode($_POST['items']??'[]',true);$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');if(!$items||!$name||!$phone||!$address){$msg='Please complete your details and add products to cart.';}else{try{$pdo->beginTransaction();$total=0;$valid=[];foreach($items as $it){$id=(int)($it['id']??0);$qty=max(1,min(99,(int)($it['qty']??1)));$q=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? AND active=1 FOR UPDATE');$q->execute([$id]);$p=$q->fetch();if(!$p||$p['stock']<$qty)throw new Exception('A product is unavailable or has insufficient stock.');$total+=(float)$p['price']*$qty;$valid[]=[$p,$qty];}$q=$pdo->prepare('INSERT INTO orders(user_id,customer_name,phone,address,total) VALUES(?,?,?,?,?)');$q->execute([current_user()['id']??null,$name,$phone,$address,$total]);$oid=(int)$pdo->lastInsertId();foreach($valid as [$p,$qty]){$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,price) VALUES(?,?,?,?,?)')->execute([$oid,$p['id'],$p['name'],$qty,$p['price']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$p['id']]);}$pdo->commit();$msg='Order placed successfully! Your order number is #'.$oid.'.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg=$e instanceof PDOException?'Could not place order. Please try again.':$e->getMessage();}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout</title><link rel="stylesheet" href="assets/css/store-theme.css"></head><body><header class="store-header"><a class="store-logo" href="index.php">🛒 Mahavir Provision Store</a></header><main class="store-container"><section class="auth-card"><h1>Checkout</h1><?php if($msg):?><p class="alert"><?=e($msg)?></p><?php endif;?><form method="post" id="checkout-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="items" id="checkout-items"><label>Full name</label><input name="name" value="<?=e(current_user()['name']??'')?>" required><label>Mobile number</label><input name="phone" required><label>Delivery address</label><textarea name="address" required></textarea><button class="primary-btn full">Place order</button></form></section></main><script src="assets/js/app.js"></script><script>document.getElementById('checkout-items').value=JSON.stringify(getCart());if(!getCart().length)document.getElementById('checkout-form').insertAdjacentHTML('beforebegin','<p class="alert">Your cart is empty. <a href="index.php">Shop products</a></p>');</script></body></html>